let _markdown = "\n\n<FeedbackBlock id=\"3fc29d91a0ae80e3\" body=\"The context provider of all the components, including next-themes and <FrameworkProvider />. It should be located at the root layout.\">\n  The context provider of all the components, including `next-themes` and [`<FrameworkProvider />`](/docs/headless#installation). It should be located at the root layout.\n</FeedbackBlock>\n\nUsage [#usage]\n\n<FeedbackBlock id=\"a249e6011f44994e\" body=\"Import it according to your React.js framework:\">\n  Import it according to your React.js framework:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Next.js\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Next.js\">\n      Next.js\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"React Router\">\n      React Router\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Tanstack\">\n      Tanstack\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Waku\">\n      Waku\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Next.js\">\n    ```jsx\n    import { RootProvider } from 'fumadocs-ui/provider/next';\n\n    export default function Layout({ children }) {\n      return (\n        <html lang=\"en\">\n          <body>\n            <RootProvider>{children}</RootProvider>\n          </body>\n        </html>\n      );\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"React Router\">\n    ```jsx\n    import { RootProvider } from 'fumadocs-ui/provider/react-router';\n\n    export function Layout({ children }) {\n      return (\n        <html lang=\"en\">\n          <body>\n            <RootProvider>{children}</RootProvider>\n          </body>\n        </html>\n      );\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Tanstack\">\n    ```jsx\n    import {\n      HeadContent,\n      Scripts,\n    } from '@tanstack/react-router';\n    import { RootProvider } from 'fumadocs-ui/provider/tanstack';\n\n    function RootDocument({ children }: { children: React.ReactNode }) {\n      return (\n        <html suppressHydrationWarning>\n          <head>\n            <HeadContent />\n          </head>\n          <body className=\"flex flex-col min-h-screen\">\n            <RootProvider>{children}</RootProvider>\n            <Scripts />\n          </body>\n        </html>\n      );\n    }\n\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Waku\">\n    ```jsx\n    import { RootProvider } from 'fumadocs-ui/provider/waku';\n\n    export default function Layout({ children }) {\n      return (\n        <html lang=\"en\">\n          <body>\n            <RootProvider>{children}</RootProvider>\n          </body>\n        </html>\n      );\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nSearch Dialog [#search-dialog]\n\n<FeedbackBlock id=\"ddc8f5fdda59361c\" body=\"Customize or disable the search dialog with search option.\">\n  Customize or disable the search dialog with `search` option.\n</FeedbackBlock>\n\n```jsx\n<RootProvider\n  search={{\n    enabled: false,\n  }}\n>\n  {children}\n</RootProvider>\n```\n\n<FeedbackBlock id=\"4ed430adcf40cd83\" body=\"Learn more from Search.\">\n  Learn more from [Search](/docs/ui/search).\n</FeedbackBlock>\n\nTheme Provider [#theme-provider]\n\n<FeedbackBlock\n  id=\"61a044f90919a1d2\"\n  body=\"Fumadocs supports light/dark modes with next-themes.\nCustomise or disable it with theme option.\"\n>\n  Fumadocs supports light/dark modes with [`next-themes`](https://github.com/pacocoursey/next-themes).\n  Customise or disable it with `theme` option.\n</FeedbackBlock>\n\n```jsx\n<RootProvider\n  theme={{\n    enabled: false,\n  }}\n>\n  {children}\n</RootProvider>\n```\n\n<FeedbackBlock id=\"7a12b021132b50c3\" body=\"You can also install & reference next-themes in your code for managing themes.\">\n  You can also install & reference `next-themes` in your code for managing themes.\n</FeedbackBlock>\n";
